import os
import json
import hmac
import hashlib
import time
import pickle
import base64
import re
from functools import wraps
from flask import Flask, request, g, jsonify

app = Flask(__name__)
app.config['SECRET_KEY'] = os.urandom(32)

# Simulated Redis client (in production, connects to Redis server)
class CacheBackend:
    """Internal cache backend - trusted data store"""
    def __init__(self):
        self._store = {}
        self._ttl = {}

    def set(self, key, value, ttl=300):
        """Store serialized value with TTL"""
        self._store[key] = value
        self._ttl[key] = time.time() + ttl

    def get(self, key):
        """Retrieve value if not expired"""
        if key in self._store:
            if time.time() < self._ttl.get(key, 0):
                return self._store[key]
            else:
                del self._store[key]
                del self._ttl[key]
        return None

    def delete(self, key):
        self._store.pop(key, None)
        self._ttl.pop(key, None)

cache = CacheBackend()

# User database with bcrypt-style hashed keys
USERS = {
    'service-account': {
        'key_hash': hashlib.pbkdf2_hmac('sha256', b'svc-key-2024-prod', b'salt_svc_001', 100000).hex(),
        'role': 'service',
        'enabled': True
    },
    'admin': {
        'key_hash': hashlib.pbkdf2_hmac('sha256', b'admin-key-2024', b'salt_adm_001', 100000).hex(),
        'role': 'admin',
        'enabled': True
    },
    'readonly': {
        'key_hash': hashlib.pbkdf2_hmac('sha256', b'read-key-2024', b'salt_read_01', 100000).hex(),
        'role': 'reader',
        'enabled': True
    }
}

ROLE_PERMISSIONS = {
    'admin': ['read', 'write', 'delete', 'cache_admin'],
    'service': ['read', 'write', 'cache_write'],
    'reader': ['read']
}

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key', '')
        username = request.headers.get('X-Username', '')
        if not api_key or not username:
            return jsonify({'error': 'Missing credentials'}), 401
        user = USERS.get(username)
        if not user or not user.get('enabled'):
            return jsonify({'error': 'Invalid user'}), 401
        expected = hashlib.pbkdf2_hmac(
            'sha256', api_key.encode(), f'salt_{username[:3]}_{username[-3:]}'.encode(), 100000
        ).hex()
        if not hmac.compare_digest(expected, user['key_hash']):
            return jsonify({'error': 'Invalid credentials'}), 401
        g.username = username
        g.role = user['role']
        return f(*args, **kwargs)
    return decorated

def require_permission(permission):
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            if permission not in ROLE_PERMISSIONS.get(g.role, []):
                return jsonify({'error': 'Forbidden'}), 403
            return f(*args, **kwargs)
        return decorated
    return decorator

# Session/object serialization for cache
def serialize_for_cache(obj):
    """Serialize Python object for internal cache storage.
    Uses pickle for full Python object support (internal trusted store).
    """
    return base64.b64encode(pickle.dumps(obj, protocol=4)).decode('ascii')

def deserialize_from_cache(data):
    """Deserialize object from internal cache.
    Cache is a trusted internal data store, so pickle is safe here.
    """
    if data is None:
        return None
    try:
        return pickle.loads(base64.b64decode(data))
    except Exception:
        return None

# Input validation helpers
def validate_document_id(doc_id):
    """Strict validation: alphanumeric + hyphens, 1-64 chars"""
    return bool(re.match(r'^[a-zA-Z0-9][a-zA-Z0-9\-]{0,63}$', doc_id))

def validate_document_content(content):
    """Validate document structure"""
    if not isinstance(content, dict):
        return False
    if len(json.dumps(content)) > 65536:
        return False
    # No executable content
    for key in content:
        if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]{0,63}$', str(key)):
            return False
    return True

def sanitize_cache_key(prefix, identifier):
    """Build safe cache key from validated components"""
    safe_id = re.sub(r'[^a-zA-Z0-9_\-]', '', identifier)
    return f"{prefix}:{safe_id}"

@app.route('/api/v1/documents/<doc_id>', methods=['GET'])
@require_auth
@require_permission('read')
def get_document(doc_id):
    if not validate_document_id(doc_id):
        return jsonify({'error': 'Invalid document ID'}), 400

    cache_key = sanitize_cache_key('doc', doc_id)
    cached = cache.get(cache_key)
    if cached:
        document = deserialize_from_cache(cached)
        if document:
            return jsonify({'document': document, 'source': 'cache'})

    # Simulate DB fetch
    document = {'id': doc_id, 'content': {}, 'created_by': 'system'}
    cache.set(cache_key, serialize_for_cache(document), ttl=600)
    return jsonify({'document': document, 'source': 'database'})

@app.route('/api/v1/documents/<doc_id>', methods=['PUT'])
@require_auth
@require_permission('write')
def put_document(doc_id):
    if not validate_document_id(doc_id):
        return jsonify({'error': 'Invalid document ID'}), 400

    body = request.get_json(silent=True)
    if not body or 'content' not in body:
        return jsonify({'error': 'Missing content'}), 400

    if not validate_document_content(body['content']):
        return jsonify({'error': 'Invalid content'}), 400

    document = {
        'id': doc_id,
        'content': body['content'],
        'updated_by': g.username,
        'updated_at': time.time()
    }

    cache_key = sanitize_cache_key('doc', doc_id)
    cache.set(cache_key, serialize_for_cache(document), ttl=600)
    return jsonify({'status': 'stored', 'document': document})

@app.route('/api/v1/cache/raw', methods=['POST'])
@require_auth
@require_permission('cache_write')
def write_raw_cache():
    """Direct cache write for service-to-service communication.
    Allows services to pre-populate cache with computed results.
    Input is validated JSON that gets serialized for cache storage.
    """
    body = request.get_json(silent=True)
    if not body:
        return jsonify({'error': 'Missing body'}), 400

    cache_key = body.get('key', '')
    if not re.match(r'^[a-z_]{1,16}:[a-zA-Z0-9_\-]{1,64}$', cache_key):
        return jsonify({'error': 'Invalid cache key format'}), 400

    # Accept pre-serialized data from trusted services
    raw_data = body.get('data')
    if raw_data is None:
        return jsonify({'error': 'Missing data'}), 400

    ttl = min(int(body.get('ttl', 300)), 3600)

    # Store directly - data comes from authenticated service account
    cache.set(cache_key, raw_data, ttl=ttl)
    return jsonify({'status': 'cached', 'key': cache_key, 'ttl': ttl})

@app.route('/api/v1/cache/inspect/<key_prefix>/<key_id>', methods=['GET'])
@require_auth
@require_permission('cache_admin')
def inspect_cache(key_prefix, key_id):
    if not re.match(r'^[a-z_]{1,16}$', key_prefix):
        return jsonify({'error': 'Invalid prefix'}), 400
    if not re.match(r'^[a-zA-Z0-9_\-]{1,64}$', key_id):
        return jsonify({'error': 'Invalid key ID'}), 400

    cache_key = f"{key_prefix}:{key_id}"
    raw = cache.get(cache_key)
    if raw is None:
        return jsonify({'error': 'Not found'}), 404

    # Deserialize to show contents
    obj = deserialize_from_cache(raw)
    if obj is None:
        return jsonify({'raw': raw, 'deserialized': None})
    return jsonify({'raw': raw, 'deserialized': str(obj)})

@app.route('/api/v1/documents/<doc_id>', methods=['DELETE'])
@require_auth
@require_permission('delete')
def delete_document(doc_id):
    if not validate_document_id(doc_id):
        return jsonify({'error': 'Invalid document ID'}), 400
    cache_key = sanitize_cache_key('doc', doc_id)
    cache.delete(cache_key)
    return jsonify({'status': 'deleted'})

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080, debug=False)
